"""HTTP surface for DocScribe.

FastAPI when it is installed; otherwise a small stdlib fallback server exposing
the same routes, so the demo runs on a bare Python install. Both paths share the
handler functions below, which is the only way to keep them honest.
"""

from __future__ import annotations

import json
import os
import re
from pathlib import Path
from typing import Any

from agent import SummarizerAgent
from config import settings
from jobqueue import JobQueue, Phase
from store import Store

store = Store(settings.db_path)
agent = SummarizerAgent(store)
queue = JobQueue(store, agent)

FRONTEND_DIR = Path(__file__).resolve().parent.parent / "frontend"
_DOC_ID_RE = re.compile(r"[A-Za-z0-9_-]{1,64}")


# --------------------------------------------------------------------- handlers


def handle_health() -> dict[str, Any]:
    return {
        "status": "ok",
        "docs_dir": str(settings.docs_dir),
        "worker": queue._thread is not None,
        "phases": [phase.value for phase in Phase],
    }


def handle_list_docs() -> dict[str, Any]:
    available = sorted(path.stem for path in settings.docs_dir.glob("*.md"))
    known = {doc.doc_id: doc.to_dict() for doc in store.list_documents()}
    return {
        "documents": [known.get(doc_id, {"doc_id": doc_id, "title": doc_id, "tokens": 0}) for doc_id in available]
    }


class ValidationError(ValueError):
    """Raised when a request payload is malformed."""


def handle_create_job(payload: dict[str, Any]) -> dict[str, Any]:
    """Queue a summarization job.

    `doc_id` names a file inside the docs directory. Validating it here rather
    than deeper in the stack means a bad request fails as a 400 instead of
    surfacing as a database integrity error raised on the worker thread, where
    nothing is left to turn it back into a response.
    """
    if not isinstance(payload, dict):
        raise ValidationError("body must be a JSON object")

    doc_id = payload.get("doc_id")
    if not isinstance(doc_id, str) or not doc_id.strip():
        raise ValidationError("doc_id is required and must be a non-empty string")
    if not _DOC_ID_RE.fullmatch(doc_id):
        raise ValidationError("doc_id may only contain letters, digits, hyphens and underscores")
    if not (settings.docs_dir / f"{doc_id}.md").is_file():
        raise ValidationError(f"no such document: {doc_id}")

    job_id = queue.submit(doc_id)
    return {"job_id": job_id, "doc_id": doc_id, "state": "queued"}


def handle_get_job(job_id: str) -> dict[str, Any] | None:
    return store.get_job(job_id)


def handle_list_jobs() -> dict[str, Any]:
    return {"jobs": store.list_jobs()}


def handle_reset() -> dict[str, Any]:
    store.clear_summaries()
    return {"status": "summaries cleared"}


# ----------------------------------------------------------------------- FastAPI

try:  # pragma: no cover - exercised by whichever branch the environment allows
    from fastapi import FastAPI, HTTPException
    from fastapi.responses import FileResponse
    from fastapi.staticfiles import StaticFiles

    app = FastAPI(title="DocScribe", version="0.3.0")

    @app.on_event("startup")
    def _startup() -> None:
        if settings.enable_worker:
            queue.start()

    @app.on_event("shutdown")
    def _shutdown() -> None:
        queue.stop()

    @app.get("/health")
    def health() -> dict[str, Any]:
        return handle_health()

    @app.get("/docs-list")
    def list_docs() -> dict[str, Any]:
        return handle_list_docs()

    @app.post("/jobs")
    def create_job(payload: dict) -> dict[str, Any]:
        return handle_create_job(payload)

    @app.get("/jobs")
    def list_jobs() -> dict[str, Any]:
        return handle_list_jobs()

    @app.get("/jobs/{job_id}")
    def get_job(job_id: str) -> dict[str, Any]:
        job = handle_get_job(job_id)
        if job is None:
            raise HTTPException(status_code=404, detail="unknown job")
        return job

    @app.post("/admin/reset")
    def reset() -> dict[str, Any]:
        return handle_reset()

    if FRONTEND_DIR.exists():
        app.mount("/ui", StaticFiles(directory=str(FRONTEND_DIR), html=True), name="ui")

        @app.get("/")
        def index() -> FileResponse:
            return FileResponse(str(FRONTEND_DIR / "index.html"))

    HAS_FASTAPI = True

except ImportError:  # pragma: no cover
    app = None
    HAS_FASTAPI = False


# ------------------------------------------------------------- stdlib fallback


def _build_stdlib_server(host: str, port: int):
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    from urllib.parse import urlparse

    class Handler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def _send(self, status: int, body: Any, content_type: str = "application/json") -> None:
            raw = body if isinstance(body, bytes) else json.dumps(body).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(raw)))
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(raw)

        def log_message(self, *args: Any) -> None:  # keep the console readable
            return

        def do_GET(self) -> None:
            path = urlparse(self.path).path
            if path == "/health":
                return self._send(200, handle_health())
            if path == "/docs-list":
                return self._send(200, handle_list_docs())
            if path == "/jobs":
                return self._send(200, handle_list_jobs())
            if path.startswith("/jobs/"):
                job = handle_get_job(path.rsplit("/", 1)[-1])
                return self._send(200, job) if job else self._send(404, {"detail": "unknown job"})
            return self._serve_static(path)

        def do_POST(self) -> None:
            path = urlparse(self.path).path
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b"{}"
            try:
                payload = json.loads(raw or b"{}")
            except json.JSONDecodeError:
                return self._send(400, {"detail": "body must be JSON"})
            if path == "/jobs":
                return self._send(200, handle_create_job(payload))
            if path == "/admin/reset":
                return self._send(200, handle_reset())
            return self._send(404, {"detail": "not found"})

        def _serve_static(self, path: str) -> None:
            relative = "index.html" if path in ("/", "") else path.lstrip("/").removeprefix("ui/")
            target = (FRONTEND_DIR / relative).resolve()
            if FRONTEND_DIR.resolve() not in target.parents or not target.is_file():
                return self._send(404, {"detail": "not found"})
            types = {".html": "text/html", ".css": "text/css", ".js": "text/javascript", ".svg": "image/svg+xml"}
            self._send(200, target.read_bytes(), types.get(target.suffix, "application/octet-stream"))

    return ThreadingHTTPServer((host, port), Handler)


def main() -> None:
    host = os.environ.get("DOCSCRIBE_HOST", "127.0.0.1")
    port = int(os.environ.get("DOCSCRIBE_PORT", "8000"))
    if settings.enable_worker:
        queue.start()
    if HAS_FASTAPI:
        import uvicorn

        uvicorn.run(app, host=host, port=port, log_level="warning")
        return
    server = _build_stdlib_server(host, port)
    print(f"DocScribe (stdlib server) on http://{host}:{port}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        queue.stop()


if __name__ == "__main__":
    main()

"""Tests for chunker.py.

The chunker is the one place in this service where a bug stays invisible in the
output: a chunk split through the middle of a code fence still summarizes into
plausible-looking prose. So these tests pin the structural guarantees rather than
the text, because the text will look fine either way.
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from chunker import chunk_markdown, iter_blocks, outline

SAMPLE = """# Title

An opening paragraph long enough to matter when the splitter is deciding
where a chunk should end.

## Section one

Some prose that belongs with the heading above it.

```python
def keep_me_whole():
    return "this fence must never be split"
```

## Section two

- first item
- second item
"""


def test_fenced_code_is_never_split() -> None:
    for chunk in chunk_markdown(SAMPLE, target_tokens=20, max_tokens=40):
        assert chunk.text.count("```") % 2 == 0, f"unbalanced fence in chunk {chunk.index}"


def test_no_content_is_lost() -> None:
    chunks = chunk_markdown(SAMPLE, target_tokens=30, max_tokens=60)
    joined = "\n".join(chunk.text for chunk in chunks)
    for block in iter_blocks(SAMPLE):
        assert block.text in joined, f"lost block: {block.text[:40]!r}"


def test_a_chunk_is_never_a_bare_heading() -> None:
    for chunk in chunk_markdown(SAMPLE, target_tokens=30, max_tokens=60):
        stripped = chunk.text.strip()
        if stripped.startswith("#"):
            assert "\n" in stripped, f"chunk {chunk.index} is a heading with nothing under it"


def test_breadcrumb_describes_where_the_chunk_starts() -> None:
    chunks = chunk_markdown(SAMPLE, target_tokens=20, max_tokens=40)
    assert chunks[0].heading_path == ["Title"]
    assert any("Section one" in chunk.heading_path for chunk in chunks)


def test_empty_document_produces_no_chunks() -> None:
    assert chunk_markdown("   \n\n  ") == []


def test_outline_lists_headings_in_order() -> None:
    assert outline(SAMPLE) == [(1, "Title"), (2, "Section one"), (2, "Section two")]


def test_rejects_nonsense_limits() -> None:
    for bad in ((0, 10), (10, 0), (700, 400)):
        try:
            chunk_markdown(SAMPLE, target_tokens=bad[0], max_tokens=bad[1])
        except ValueError:
            continue
        raise AssertionError(f"accepted invalid limits {bad}")


def main() -> int:
    tests = [value for name, value in sorted(globals().items()) if name.startswith("test_")]
    failures = 0
    for test in tests:
        try:
            test()
        except AssertionError as exc:
            failures += 1
            print(f"FAIL {test.__name__}: {exc}")
        else:
            print(f"ok   {test.__name__}")
    print(f"\n{len(tests) - failures}/{len(tests)} passed")
    return 1 if failures else 0


if __name__ == "__main__":
    raise SystemExit(main())

/* DocScribe — visual theme.
 *
 * Everything the robot looks like is driven by the custom properties below.
 * Change a value here and the whole illustration follows; nothing downstream
 * hardcodes a colour.
 */

:root {
  /* ---- Robot palette --------------------------------------------------- */
  --robot-fill:      #F4A340;   /* warm amber */
  --robot-fill-dark: #D4822A;   /* shaded panels */
  --robot-stroke:    #000000;   /* black borders */
  --stroke-width:    5px;
  --stroke-width-thin: 3px;

  /* ---- Props ----------------------------------------------------------- */
  --book-fill:       #FFF8EE;
  --book-spine:      #F4A340;
  --page-line:       #E0CDB4;
  --screen-fill:     #1C1408;
  --screen-text:     #F4A340;
  --gear-fill:       #FFF8EE;
  --eye-fill:        #000000;
  --accent:          #F4A340;

  /* ---- Page ------------------------------------------------------------ */
  --bg:              #F4F8FA;
  --surface:         #FFFFFF;
  --ink:             #0E1417;
  --ink-muted:       #59696F;
  --border:          #000000;
  --radius:          14px;

  /* ---- Motion ---------------------------------------------------------- */
  --beat:            1.4s;
  --ease:            cubic-bezier(0.45, 0.05, 0.35, 1);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 32px 20px 56px;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 ui-sans-serif, -apple-system, "Segoe UI", Roboto, sans-serif;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

header { text-align: center; max-width: 620px; }
header h1 { margin: 0 0 6px; font-size: 30px; letter-spacing: -0.02em; }
header p { margin: 0; color: var(--ink-muted); }

/* ------------------------------------------------------------------ stage */

.stage {
  width: min(560px, 100%);
  background: var(--surface);
  border: var(--stroke-width) solid var(--border);
  border-radius: var(--radius);
  padding: 20px 20px 12px;
  box-shadow: 6px 6px 0 var(--border);
}

.stage svg { display: block; width: 100%; height: auto; }

.phase-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 10px;
  padding-top: 10px;
  border-top: var(--stroke-width-thin) solid var(--border);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.phase-label .detail {
  text-transform: none;
  letter-spacing: 0;
  color: var(--ink-muted);
  font-size: 13px;
  text-align: right;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.progress {
  width: min(560px, 100%);
  height: 14px;
  background: var(--surface);
  border: var(--stroke-width-thin) solid var(--border);
  border-radius: 999px;
  overflow: hidden;
}
.progress > span {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--accent);
  transition: width 0.35s var(--ease);
}

/* ----------------------------------------------------------------- robot */

.robot-part {
  fill: var(--robot-fill);
  stroke: var(--robot-stroke);
  stroke-width: var(--stroke-width);
  stroke-linejoin: round;
}
.robot-part.shaded { fill: var(--robot-fill-dark); }
.eye { fill: var(--eye-fill); stroke: none; }
.book-page { fill: var(--book-fill); stroke: var(--robot-stroke); stroke-width: var(--stroke-width); }
.book-spine { fill: var(--book-spine); stroke: var(--robot-stroke); stroke-width: var(--stroke-width); }
.page-rule { stroke: var(--page-line); stroke-width: var(--stroke-width-thin); stroke-linecap: round; }
.screen { fill: var(--screen-fill); stroke: var(--robot-stroke); stroke-width: var(--stroke-width); }
.screen-line { stroke: var(--screen-text); stroke-width: var(--stroke-width-thin); stroke-linecap: round; }
.gear { fill: var(--gear-fill); stroke: var(--robot-stroke); stroke-width: var(--stroke-width-thin); }
.bubble { fill: var(--surface); stroke: var(--robot-stroke); stroke-width: var(--stroke-width); }
.desk { stroke: var(--robot-stroke); stroke-width: var(--stroke-width); stroke-linecap: round; }

/* Props are hidden by default and revealed per phase. */
#book, #thought, #workstation { opacity: 0; transition: opacity 0.3s var(--ease); }
[data-phase="reading"] #book,
[data-phase="thinking"] #book,
[data-phase="thinking"] #thought,
[data-phase="writing"] #workstation,
[data-phase="done"] #workstation { opacity: 1; }

/* ------------------------------------------------------------- animations */

@keyframes blink      { 0%, 92%, 100% { transform: scaleY(1); } 96% { transform: scaleY(0.1); } }
@keyframes antenna    { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }
@keyframes page-turn  { 0%, 100% { transform: rotateY(0deg); } 50% { transform: rotateY(-38deg); } }
@keyframes scan       { 0% { transform: translateX(0); } 100% { transform: translateX(26px); } }
@keyframes spin       { to { transform: rotate(360deg); } }
@keyframes spin-back  { to { transform: rotate(-360deg); } }
@keyframes bob        { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(3px); } }
@keyframes type-flash { 0%, 100% { opacity: 0.25; } 50% { opacity: 1; } }
@keyframes nod        { 0%, 100% { transform: rotate(0deg); } 50% { transform: rotate(4deg); } }

#eyes { animation: blink 4s infinite steps(1, end); transform-origin: 200px 130px; }
#antenna-tip { animation: antenna var(--beat) ease-in-out infinite; transform-origin: center; }

[data-phase="reading"] #page-right { animation: page-turn 2.2s var(--ease) infinite; transform-origin: 200px 248px; }
[data-phase="reading"] #scan-dot { animation: scan 1.1s var(--ease) infinite alternate; }
[data-phase="reading"] #head { animation: nod 3s ease-in-out infinite; transform-origin: 200px 180px; }

[data-phase="thinking"] #gear-big { animation: spin 3s linear infinite; transform-origin: 310px 64px; }
[data-phase="thinking"] #gear-small { animation: spin-back 2s linear infinite; transform-origin: 346px 92px; }

[data-phase="writing"] #arm-left { animation: bob 0.42s ease-in-out infinite; transform-origin: 129px 205px; }
[data-phase="writing"] #arm-right { animation: bob 0.42s ease-in-out infinite reverse; transform-origin: 271px 205px; }
[data-phase="writing"] .screen-line { animation: type-flash 0.9s ease-in-out infinite; }
[data-phase="writing"] .screen-line:nth-of-type(2) { animation-delay: 0.15s; }
[data-phase="writing"] .screen-line:nth-of-type(3) { animation-delay: 0.3s; }
[data-phase="writing"] .screen-line:nth-of-type(4) { animation-delay: 0.45s; }

[data-phase="done"] #eyes { animation: none; }
[data-phase="failed"] .robot-part { fill: #E9EDEF; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

/* ------------------------------------------------------------------ panel */

.panel {
  width: min(560px, 100%);
  background: var(--surface);
  border: var(--stroke-width) solid var(--border);
  border-radius: var(--radius);
  padding: 18px 20px;
  box-shadow: 6px 6px 0 var(--border);
}
.panel h2 { margin: 0 0 10px; font-size: 15px; text-transform: uppercase; letter-spacing: 0.1em; }
.panel ul { margin: 0; padding-left: 20px; }
.panel li { margin-bottom: 8px; }
.panel .empty { color: var(--ink-muted); font-style: italic; }

.controls { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; justify-content: center; }

select, button {
  font: inherit;
  padding: 9px 14px;
  border: var(--stroke-width-thin) solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  cursor: pointer;
}
button { background: var(--accent); font-weight: 600; box-shadow: 3px 3px 0 var(--border); }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--border); }
button[disabled] { opacity: 0.5; cursor: not-allowed; box-shadow: none; transform: none; }

.offline-note {
  width: min(560px, 100%);
  font-size: 13px;
  color: var(--ink-muted);
  text-align: center;
}
